// Load the standalone runtime only when the student opens it.
async function decodeMicroscope(){
 if(microscopePreparation)return microscopePreparation;
 microscopePreparation=fetch('./runtime/microscope.html').then(async response=>{
  if(!response.ok)throw new Error('Runtime unavailable: '+response.status);
  const html=await response.text();
  const base=new URL('./runtime/microscope.html',document.baseURI).href;
  return html.replace(/<head([^>]*)>/i,'<head$1><base href="'+base+'">');
 }).catch(error=>{microscopePreparation=null;throw error});
 return microscopePreparation;
}
function primeMicroscope(){
 if(microscopeLoadPromise)return microscopeLoadPromise;
 microscopeLoadPromise=decodeMicroscope().then(html=>new Promise((resolve,reject)=>{
  const frame=$('microscopeFrame');
  const timer=setTimeout(()=>{frame.removeEventListener('load',loaded);microscopeLoadPromise=null;reject(new Error('Runtime timeout'))},30000);
  function loaded(){clearTimeout(timer);microscopeMounted=true;microscopeFrameReady=true;resolve(html)}
  frame.addEventListener('load',loaded,{once:true});frame.srcdoc=html;
 })).catch(error=>{microscopeLoadPromise=null;throw error});
 return microscopeLoadPromise;
}
