const LAB_STORAGE='ml-lab-learning-v1';
// Content packs are device-specific. Platform screens only consume this registry.


const instrumentRegistry=devices.map(d=>{const pack=contentPacks[d.id]||{terms:[],resources:[],learning:[]};return {...d,field:d.field||fields[d.id]||'other',pack,resources:resourceBlueprint.map(r=>{const specific=pack.resources.find(v=>v.id===r.id);return {...r,...specific,available:r.kind==='lectures'?d.links.length>0:r.kind==='notes'?true:!!specific&&!!pack.runtime}})}});
const findInstrument=id=>instrumentRegistry.find(d=>d.id===id);
const nameOf=d=>language==='en'?d.en:d.ar;
const resourceName=r=>language==='en'?r.en:r.ar;
const runtimeAdapters={microscope:{ready:primeMicroscope,activate:(device,resource)=>navigate('runtime/'+device.id+'/'+resource.id),accepts:event=>event.source===$('microscopeFrame').contentWindow,send:(section,part)=>$('microscopeFrame').contentWindow?.postMessage({type:'lab-navigate',section,part},'*')}};
const emptyRecord=()=>({modules:{},notes:'',parts:[],mistakes:[],quizAttempts:0,bestQuiz:0,lastQuiz:null,lastQuizId:null,scenarios:[],reviewSchedule:{}});
const emptyLearning=()=>({version:2,visits:{},favorites:[],notes:'',lastDevice:null,lastModule:null,progress:{}});
function validateLearning(input){if(!input||typeof input!=='object'||Array.isArray(input)||![1,2].includes(input.version))throw Error('schema');const out=emptyLearning();if(typeof input.notes!=='string'||input.notes.length>200000)throw Error('notes');out.notes=input.notes;if(!Array.isArray(input.favorites)||input.favorites.length>100)throw Error('favorites');out.favorites=[...new Set(input.favorites)].filter(id=>findInstrument(id));if(!input.visits||typeof input.visits!=='object')throw Error('visits');for(const d of instrumentRegistry){const time=input.visits[d.id];if(Number.isFinite(time)&&time>0&&time<=8640000000000000)out.visits[d.id]=time}
 if(input.version===2&&(!input.progress||typeof input.progress!=='object'||Array.isArray(input.progress)))throw Error('progress');let records=input.progress||{};
 // Migrate older single-device progress without losing notes, scores or favorites.
 if(input.version===1){records={microscope:{...input,modules:input.sections||{}}};out.lastModule=({free:'explore',notes:'material',parts:'parts',quiz:'quiz',scenario:'scenario'})[input.lastSection]||null;if(out.lastModule==='parts')out.lastModule='photo'}
 out.lastDevice=findInstrument(input.lastDevice)?input.lastDevice:null;if(input.version===2)out.lastModule=input.lastModule==='parts'?'photo':typeof input.lastModule==='string'?input.lastModule:null;
 for(const d of instrumentRegistry){const r=records[d.id];if(!r)continue;const clean=emptyRecord();clean.notes=typeof r.notes==='string'&&input.version===2?r.notes:'';if(clean.notes.length>200000)throw Error('notes');for(const k of ['parts','mistakes']){if(r[k]!==undefined&&!Array.isArray(r[k]))throw Error('parts');clean[k]=[...new Set(r[k]||[])].filter(i=>Number.isInteger(i)&&i>=0&&i<d.pack.terms.length)}for(const k of ['quizAttempts','bestQuiz']){if(r[k]!==undefined&&(!Number.isInteger(r[k])||r[k]<0||r[k]>(k==='bestQuiz'?(d.pack.quizTotal||0):100000)))throw Error('score');clean[k]=r[k]||0}clean.lastQuiz=Number.isFinite(r.lastQuiz)?r.lastQuiz:null;clean.lastQuizId=typeof r.lastQuizId==='string'?r.lastQuizId.slice(0,100):null;for(const res of [...d.resources,...(d.pack.learning||[])]){const legacy=({material:'notes',explore:'free',photo:'parts'})[res.id]||res.id;const time=r.modules?.[res.id]||r.modules?.[legacy];if(Number.isFinite(time)&&time>0)clean.modules[res.id]=time}clean.scenarios=Array.isArray(r.scenarios)?[...new Set(r.scenarios)].filter(id=>d.resources.some(res=>res.id==='scenario')&&id==='illumination'):[];for(let i=0;i<d.pack.terms.length;i++){const review=r.reviewSchedule?.[i];if(review&&Number.isFinite(review.due)&&Number.isInteger(review.streak)&&review.streak>=0&&review.streak<=20)clean.reviewSchedule[i]={due:review.due,streak:review.streak}}out.progress[d.id]=clean}return out}
let labState=emptyLearning();try{const raw=JSON.parse(localStorage.getItem(LAB_STORAGE)||'null');if(raw)labState=validateLearning(raw)}catch{}
function deviceProgress(id){return labState.progress[id]||(labState.progress[id]=emptyRecord())}
function saveLearning(){try{localStorage.setItem(LAB_STORAGE,JSON.stringify(labState));return true}catch{return false}}
let runtimeContext='device',currentResourceId='explore',pendingRuntimePart=null;let currentDeviceId=null,learningScope='all',activeLearnTab='guide',toastTimer;
function toast(message){$('platformToast').textContent=message;$('platformToast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('platformToast').classList.remove('visible'),2200)}
function markVisit(id,module){if(!findInstrument(id))return;labState.visits[id]=Date.now();labState.lastDevice=id;labState.lastModule=module||null;if(module)deviceProgress(id).modules[module]=Date.now();saveLearning()}
function toggleFavorite(id){if(labState.favorites.includes(id)){labState.favorites=labState.favorites.filter(v=>v!==id);toast(tx('favoriteRemoved'))}else{labState.favorites.push(id);toast(tx('favoriteAdded'))}saveLearning();renderPlatform()}
function openInstrument(id){if(findInstrument(id))navigate('device/'+id)}
