function renderProgress(){const records=Object.values(labState.progress);$('statVisited').textContent=Object.keys(labState.visits).length+' / '+instrumentRegistry.length;$('statParts').textContent=records.reduce((n,r)=>n+Object.keys(r.modules).length,0);$('statQuizzes').textContent=records.reduce((n,r)=>n+r.quizAttempts,0);$('statBest').textContent=labState.favorites.length;const list=$('deviceProgressList');list.replaceChildren();for(const d of instrumentRegistry){const r=deviceProgress(d.id),detail=document.createElement('details');detail.className='termCard';const summary=document.createElement('summary'),b=document.createElement('b'),small=document.createElement('span');b.textContent=nameOf(d);small.textContent=labState.visits[d.id]?Object.keys(r.modules).length+' '+tx('resourcesOpened'):tx('notYet');summary.append(b,small);detail.append(summary);if(d.pack.terms.length){const p=document.createElement('p');p.textContent=r.parts.length+' / '+d.pack.terms.length+' · '+tx('reviewed');detail.append(p)}if(d.pack.quizTotal){const p=document.createElement('p');p.textContent=tx('best')+': '+(r.quizAttempts?r.bestQuiz+' / '+d.pack.quizTotal:tx('notYet'));detail.append(p)}detail.append(progressRow(tx('openDevice'),tx('availableResources'),()=>openInstrument(d.id)));list.append(detail)}
 const fav=$('favoriteList');fav.replaceChildren();$('noFavorites').hidden=labState.favorites.length>0;for(const id of labState.favorites){const d=findInstrument(id);if(d)fav.append(progressRow(nameOf(d),tx('openDevice'),()=>openInstrument(id)))}const recent=$('recentList');recent.replaceChildren();$('noActivity').hidden=Object.keys(labState.visits).length>0;for(const id of Object.keys(labState.visits).sort((a,b)=>labState.visits[b]-labState.visits[a]).slice(0,5)){const d=findInstrument(id);recent.append(progressRow(nameOf(d),new Intl.DateTimeFormat(language==='ar'?'ar':'en',{month:'short',day:'numeric'}).format(labState.visits[id]),()=>openInstrument(id)))}const missed=$('mistakeList');missed.replaceChildren();let count=0;for(const d of instrumentRegistry)for(const i of deviceProgress(d.id).mistakes){const t=d.pack.terms[i];if(!t)continue;count++;missed.append(progressRow(language==='en'?t.en:t.ar,nameOf(d),()=>activateResource(d.id,'parts',i)))}$('noMistakes').hidden=count>0;renderReviewScope();}
let reviewScope='all',reviewQueue=[],reviewPosition=0,reviewRevealed=false;
function dueCards(all=false){return allTerms(reviewScope).filter(({device,index})=>{const r=deviceProgress(device.id);return all||(r.mistakes.includes(index)&&(!r.reviewSchedule[index]||r.reviewSchedule[index].due<=Date.now()))})}
function renderReviewScope(){const old=reviewScope;$('reviewScope').replaceChildren();for(const id of ['all',...instrumentRegistry.filter(d=>d.pack.terms.length).map(d=>d.id)]){const op=document.createElement('option');op.value=id;op.textContent=id==='all'?tx('allDevices'):nameOf(findInstrument(id));$('reviewScope').append(op)}$('reviewScope').value=old;$('reviewDueCount').textContent=dueCards().length+' '+tx('reviewDue');$('reviewAvailability').textContent=tx('reviewAvailability')+': '+instrumentRegistry.filter(d=>d.pack.terms.length).map(nameOf).join('، ')}
function startReview(all=false){reviewQueue=dueCards(all);reviewPosition=0;$('reviewDialog').showModal();showReviewCard()}
function showReviewCard(){reviewRevealed=false;const item=reviewQueue[reviewPosition],done=!item;$('reviewActions').hidden=true;$('revealReview').hidden=done;$('reviewPartOnDevice').hidden=done;$('reviewCardCount').textContent=done?'':(reviewPosition+1)+' / '+reviewQueue.length+' · '+nameOf(item.device);$('reviewCardTitle').textContent=done?(reviewQueue.length?tx('reviewFinished'):tx('reviewNoDue')):language==='en'?item.term.en:item.term.ar;$('reviewCardAnswer').textContent=done?tx('reviewFinishDesc'):(language==='en'?'What does this part do?':'شو وظيفة هذا الجزء؟')}
function revealReview(){const item=reviewQueue[reviewPosition];if(!item)return;reviewRevealed=true;$('reviewCardAnswer').textContent=language==='en'?item.term.english:item.term.desc;$('reviewActions').hidden=false;$('revealReview').hidden=true}
function rateReview(known){const item=reviewQueue[reviewPosition];if(!item||!reviewRevealed)return;const r=deviceProgress(item.device.id),old=r.reviewSchedule[item.index]||{streak:0},streak=known?Math.min(old.streak+1,20):0,days=[1,3,7,14,30][Math.min(Math.max(streak-1,0),4)];r.reviewSchedule[item.index]={streak,due:Date.now()+(known?days*86400000:600000)};saveLearning();reviewPosition++;showReviewCard();renderReviewScope()}
function renderPlatform(){if(!platformReady)return;$('openSettings').setAttribute('aria-label',translations[language].settings);document.querySelector('.hubbrand b').textContent=language==='en'?'Medical Laboratory':'مختبر الطبّ المخبري';renderSettingsCopy();document.querySelectorAll('[data-p]').forEach(e=>e.textContent=tx(e.dataset.p));const greeting=document.querySelector('.homeWelcome h1');if(greeting){greeting.replaceChildren();for(const phrase of(language==='en'?['Welcome to the','Medical Laboratory']:['أهلًا ومرحبًا بكم','في مختبر الطبّ المخبري'])){const line=document.createElement('span');line.textContent=phrase;greeting.append(line)}}$('deviceSearch').placeholder=tx('search');$('termSearch').placeholder=tx('termSearch');$('studentNotes').placeholder=tx('notesPlaceholder');renderHome();renderCatalog();renderLearn();renderProgress();renderChemistry();if(currentDeviceId)renderDevice();if(currentPage==='deviceNotes')renderDeviceNotes();$('globalQuery').placeholder=tx('searchHint');$('openGlobalSearch').setAttribute('aria-label',tx('globalSearch'));$('backDevices').textContent=tx(currentPage==='chemistry'?'backHome':currentPage==='microscope'&&runtimeContext==='learn'?'backToLearn':['microscope','deviceNotes'].includes(currentPage)?'backToDevice':'backToCatalog');for(const b of document.querySelectorAll('.bottomNav button,.desktopNav button')){const active=b.dataset.route===(currentPage==='chemistry'?'home':currentPage==='microscope'&&runtimeContext==='learn'?'learn':['instrument','deviceNotes','microscope'].includes(currentPage)?'devices':currentPage);if(active)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current')}if($('globalSearchDialog').open)renderGlobalSearch()}
let backupReadToken=0,backupCandidate=null,searchReturnFocus=null;
function mergeLearning(a,b){const out=validateLearning(a),other=validateLearning(b);out.favorites=[...new Set([...out.favorites,...other.favorites])];if(other.notes&&!out.notes.includes(other.notes))out.notes=out.notes?out.notes+'\n\n———\n\n'+other.notes:other.notes;if(out.notes.length>200000)throw Error('notes');for(const d of instrumentRegistry){const r=out.progress[d.id]||(out.progress[d.id]=emptyRecord()),q=other.progress[d.id];if(other.visits[d.id])out.visits[d.id]=Math.max(out.visits[d.id]||0,other.visits[d.id]);if(!q)continue;for(const key of ['parts','mistakes','scenarios'])r[key]=[...new Set([...r[key],...q[key]])];for(const [key,time]of Object.entries(q.modules))r.modules[key]=Math.max(r.modules[key]||0,time);r.quizAttempts=Math.max(r.quizAttempts,q.quizAttempts);r.bestQuiz=Math.max(r.bestQuiz,q.bestQuiz);if((q.lastQuiz||0)>(r.lastQuiz||0)){r.lastQuiz=q.lastQuiz;r.lastQuizId=q.lastQuizId}if(q.notes&&!r.notes.includes(q.notes))r.notes=r.notes?r.notes+'\n\n———\n\n'+q.notes:q.notes;if(r.notes.length>200000)throw Error('notes');for(const [i,review]of Object.entries(q.reviewSchedule))if(!r.reviewSchedule[i]||review.due>r.reviewSchedule[i].due)r.reviewSchedule[i]=review}if((other.visits[other.lastDevice]||0)>(a.visits[a.lastDevice]||0)){out.lastDevice=other.lastDevice;out.lastModule=other.lastModule}return out}
function exportLearning(){const payload={format:'medical-lab-backup',version:2,exportedAt:new Date().toISOString(),learning:validateLearning(labState)},blob=new Blob([JSON.stringify(payload,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='MedicalLab_Backup_'+new Date().toISOString().slice(0,10)+'.json';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);toast(tx('exportDone'))}
function openRestore(){backupReadToken++;backupCandidate=null;$('backupFile').value='';$('backupSummary').textContent=tx('restoreEmpty');$('confirmRestore').disabled=true;$('restoreMode').value='merge';$('restoreFeedback').textContent='';$('restoreDialog').showModal()}
async function readBackupFile(file){const token=++backupReadToken;backupCandidate=null;$('confirmRestore').disabled=true;$('backupSummary').textContent=tx('restoreEmpty');if(!file)return;if(file.size>2097152){$('restoreFeedback').textContent=tx('restoreLarge');return}try{const text=await file.text();if(token!==backupReadToken)return;const data=JSON.parse(text);if(data.format!=='medical-lab-backup'||![1,2].includes(data.version))throw Error('format');backupCandidate=validateLearning(data.learning);const count=Object.values(backupCandidate.progress).reduce((n,r)=>n+r.notes.length,backupCandidate.notes.length);$('backupSummary').textContent=Object.keys(backupCandidate.visits).length+' '+tx('visited')+' · '+count+' '+tx('notesChars');$('restoreFeedback').textContent=tx('restoreReady');$('confirmRestore').disabled=false}catch{if(token!==backupReadToken)return;$('restoreFeedback').textContent=tx('restoreInvalid')}}
function confirmRestore(){if(!backupCandidate)return;try{labState=$('restoreMode').value==='replace'?validateLearning(backupCandidate):mergeLearning(labState,backupCandidate);const ok=saveLearning();backupCandidate=null;$('restoreDialog').close();renderPlatform();toast(tx(ok?'restoreDone':'sessionOnly'))}catch{$('restoreFeedback').textContent=tx('restoreInvalid')}}
function buildSearchResults(query){const q=norm(query);if(!q)return [];const rows=[];for(const d of instrumentRegistry){if(norm(d.ar+' '+d.en+' '+d.category).includes(q))rows.push({type:'device',title:nameOf(d),detail:tx(d.pack.runtime?'interactiveAvailable':'lectureAvailable'),action:()=>openInstrument(d.id)});for(const r of [...d.resources.filter(r=>r.available),...(d.pack.learning||[])])if(norm(d.ar+' '+d.en+' '+r.ar+' '+r.en).includes(q))rows.push({type:'lesson',title:resourceName(r),detail:nameOf(d),action:()=>d.pack.learning?.some(v=>v.id===r.id)?openLearningMaterial(d.id,r.id):activateResource(d.id,r.id)});const notes=deviceProgress(d.id).notes;if(notes&&norm(notes).includes(q))rows.push({type:'note',title:tx('deviceNotesLabel'),detail:nameOf(d)+' · '+notes.slice(0,80),action:()=>activateResource(d.id,'notes')})}for(const {device,index,term}of allTerms())if(norm(term.ar+' '+term.en+' '+term.desc+' '+term.english).includes(q))rows.push({type:'term',title:language==='en'?term.en:term.ar,detail:nameOf(device),action:()=>{learningScope=device.id;activeLearnTab='terms';navigate('learn');$('termSearch').value=language==='en'?term.en:term.ar;renderGlossary();const card=$('termsList').querySelector('details');if(card)card.open=true}});if(labState.notes&&norm(labState.notes).includes(q))rows.push({type:'note',title:tx('generalNotes'),detail:labState.notes.slice(0,80),action:()=>{learningScope='all';activeLearnTab='notes';navigate('learn');$('studentNotes').focus()}});for(const course of practicalCourses)if(norm(course.ar+' '+course.en).includes(q))rows.push({type:'course',title:language==='ar'?course.ar:course.en,detail:tx('soon'),action:()=>navigate('chemistry')});return rows.slice(0,24)}
function renderGlobalSearch(){const rows=buildSearchResults($('globalQuery').value);$('globalResults').replaceChildren();$('globalSearchState').textContent=!norm($('globalQuery').value)?tx('searchStart'):rows.length?rows.length+' '+tx('searchResults'):tx('searchNone');for(const row of rows)$('globalResults').append(progressRow(row.title,tx(row.type+'Result')+' · '+row.detail,()=>{$('globalSearchDialog').close();row.action()}))}
