function buildCatalog(){const container=document.querySelector('.devices');for(const card of document.querySelectorAll('.devicecard')){const id=card.dataset.catalogId||card.querySelector('[data-device]')?.dataset.device,photo=card.querySelector('.trueDevicePhoto');if(id&&photo)catalogPhotos[id]=photo.cloneNode(true)}container.replaceChildren();for(const d of instrumentRegistry){const card=document.createElement('article');card.className='devicecard';card.dataset.catalogId=d.id;const picture=document.createElement('div');picture.className='devicepicture';const number=document.createElement('span');number.className='devnumber';number.textContent=String(instrumentRegistry.indexOf(d)+1).padStart(2,'0');picture.append(number);if(d.photo||d.pack.photo){const photo=document.createElement('img');photo.className='trueDevicePhoto';photo.src=d.photo||d.pack.photo;photo.alt=d.ar+' / '+d.en;photo.loading='lazy';picture.append(photo)}else if(catalogPhotos[d.id])picture.append(catalogPhotos[d.id].cloneNode(true));else picture.insertAdjacentHTML('beforeend','<svg viewBox="0 0 110 110" aria-hidden="true"><use href="#device-'+d.icon+'"/></svg>');const badge=document.createElement('span');badge.className='devicebadge'+(d.pack.runtime?' ready':'');picture.append(badge);const favorite=document.createElement('button');favorite.className='favoriteDevice';favorite.type='button';favorite.innerHTML=icon('star',20);favorite.onclick=()=>toggleFavorite(d.id);const text=document.createElement('div');text.className='devicetext';const category=document.createElement('span');category.className='category';const title=document.createElement('h2'),english=document.createElement('p');english.lang='en';english.dir='ltr';english.textContent=d.en;const summary=document.createElement('p');summary.className='deviceSummary';const open=document.createElement('button');open.className='devicebutton'+(d.pack.runtime?' primary':'');open.dataset.device=d.id;open.append(document.createTextNode(tx('openDevice')+' '));open.insertAdjacentHTML('beforeend',icon('arrow',17));open.onclick=()=>openInstrument(d.id);text.append(category,title,english,summary,open);card.append(picture,text,favorite);container.append(card)}}

