function setupPlatform(){buildCatalog();for(const card of document.querySelectorAll('.devicecard')){const id=card.querySelector('[data-device]').dataset.device;card.dataset.catalogId=id;card.querySelector('[data-device]').onclick=()=>openInstrument(id);let b=card.querySelector('.favoriteDevice');if(!b){b=document.createElement('button');b.className='favoriteDevice';b.type='button';b.innerHTML=icon('star',20);card.append(b)}b.onclick=()=>toggleFavorite(id);if(!card.querySelector('.deviceSummary')){const p=document.createElement('p');p.className='deviceSummary';card.querySelector('.devicetext').insertBefore(p,card.querySelector('[data-device]'))}}
 for(const b of document.querySelectorAll('[data-route]'))b.onclick=()=>{if(b.dataset.learnOpen)activeLearnTab=b.dataset.learnOpen;navigate(b.dataset.route)};document.querySelectorAll('[data-developer]').forEach(b=>b.onclick=openDeveloper);document.querySelectorAll('[data-icon]').forEach(e=>e.innerHTML=icon(e.dataset.icon));$('resumeLab').onclick=resumeLearning;
 $('deviceSearch').oninput=filterCatalog;$('deviceField').onchange=filterCatalog;$('favoritesOnly').onchange=filterCatalog;$('resetFilters').onclick=()=>{$('deviceSearch').value='';$('deviceField').value='';$('favoritesOnly').checked=false;filterCatalog()};$('learningScope').onchange=()=>{learningScope=$('learningScope').value;$('termSearch').value='';$('notesStatus').textContent='';renderLearn()};$('termSearch').oninput=renderGlossary;
 const tabs=[...document.querySelectorAll('[data-learn-tab]')];for(const b of tabs){b.onclick=()=>showLearnTab(b.dataset.learnTab);b.addEventListener('keydown',e=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();const visible=tabs.filter(v=>!v.hidden),i=visible.indexOf(b),n=e.key==='Home'?0:e.key==='End'?visible.length-1:(i+(e.key==='ArrowRight'?1:-1)*(language==='ar'?-1:1)+visible.length)%visible.length;showLearnTab(visible[n].dataset.learnTab);visible[n].focus()})}
 let deviceNoteTimer;$('deviceNotesText').oninput=()=>{deviceProgress(currentDeviceId).notes=$('deviceNotesText').value;$('deviceNotesStatus').textContent=tx('saving');clearTimeout(deviceNoteTimer);deviceNoteTimer=setTimeout(()=>{$('deviceNotesStatus').textContent=saveLearning()?tx('saved'):tx('sessionOnly')},300)};let noteTimer;$('studentNotes').oninput=()=>{labState.notes=$('studentNotes').value;$('notesStatus').textContent=tx('saving');clearTimeout(noteTimer);noteTimer=setTimeout(()=>{const ok=saveLearning();$('notesStatus').textContent=ok?tx('saved'):tx('sessionOnly')},300)};window.addEventListener('pagehide',saveLearning);
 $('clearLearning').onclick=armLearningDeletion;$('clearLearningDialog').addEventListener('close',()=>$('learningDanger').classList.remove('dangerArmed'));$('cancelClearLearning').onclick=()=>$('clearLearningDialog').close();$('confirmClearLearning').onclick=()=>{labState=emptyLearning();saveLearning();$('notesStatus').textContent='';$('clearLearningDialog').close();renderPlatform();toast(tx('cleared'))};$('clearLearningDialog').addEventListener('click',e=>{if(e.target===$('clearLearningDialog'))$('clearLearningDialog').close()});$('replayWelcome').onclick=()=>{closeSettings();navigate('welcome')};$('enterLab').onclick=()=>{try{localStorage.setItem('ml-lab-onboarded','1')}catch{}navigate('home')};$('backDevices').onclick=()=>currentPage==='chemistry'?navigate('home'):currentPage==='microscope'&&runtimeContext==='learn'?navigate('learn'):['microscope','deviceNotes'].includes(currentPage)?openInstrument(currentDeviceId):navigate('devices');
 $('openGlobalSearch').innerHTML=icon('search',21);$('openGlobalSearch').onclick=$('homeSearch').onclick=openGlobalSearch;$('globalQuery').oninput=renderGlobalSearch;$('closeGlobalSearch').onclick=()=>$('globalSearchDialog').close();$('globalSearchDialog').addEventListener('close',()=>searchReturnFocus?.focus());$('exportLearning').onclick=exportLearning;$('restoreLearning').onclick=openRestore;$('chooseBackup').onclick=()=>$('backupFile').click();$('backupFile').onchange=()=>readBackupFile($('backupFile').files?.[0]);$('confirmRestore').onclick=confirmRestore;$('closeRestore').onclick=()=>$('restoreDialog').close();$('reviewScope').onchange=()=>{reviewScope=$('reviewScope').value;renderReviewScope()};$('startReview').onclick=()=>startReview(false);$('reviewAll').onclick=()=>startReview(true);$('closeReview').onclick=()=>$('reviewDialog').close();$('revealReview').onclick=revealReview;$('reviewKnown').onclick=()=>rateReview(true);$('reviewAgain').onclick=()=>rateReview(false);$('reviewPartOnDevice').onclick=()=>{const item=reviewQueue[reviewPosition];if(!item)return;$('reviewDialog').close();activateResource(item.device.id,'parts',item.index)};
 document.addEventListener('keydown',e=>{if(e.key==='/'&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName)&&!document.querySelector('dialog[open]')&&!$('settingsOverlay').classList.contains('show')){e.preventDefault();openGlobalSearch()}});for(const id of ['globalSearchDialog','restoreDialog','reviewDialog'])$(id).addEventListener('click',e=>{if(e.target===$(id))$(id).close()});platformReady=true;renderPlatform();saveLearning();}
function receiveDeviceProgress(id,data){if(!findInstrument(id))return;const d=findInstrument(id),record=deviceProgress(id);const resource=[...d.resources,...(d.pack.learning||[])].find(r=>r.section===data.section);if(resource)markVisit(id,resource.id);if(Number.isInteger(data.part)&&data.part>=0&&data.part<d.pack.terms.length&&!record.parts.includes(data.part))record.parts.push(data.part);if(Number.isInteger(data.mistake)&&data.mistake>=0&&data.mistake<d.pack.terms.length&&!record.mistakes.includes(data.mistake))record.mistakes.push(data.mistake);if(d.resources.some(r=>r.id==='quiz'&&r.available)&&data.completedQuiz&&Number.isInteger(data.score)&&data.score>=0&&data.score<=(d.pack.quizTotal||0)&&data.quizId!==record.lastQuizId){record.quizAttempts++;record.bestQuiz=Math.max(record.bestQuiz,data.score);record.lastQuiz=Date.now();record.lastQuizId=data.quizId}if(d.resources.some(r=>r.id==='scenario')&&data.completedScenario&&!record.scenarios.includes(data.completedScenario))record.scenarios.push(data.completedScenario);saveLearning()}
window.addEventListener('message',e=>{const adapter=runtimeAdapters[findInstrument(currentDeviceId)?.pack.runtime];if(currentPage!=='microscope'||!adapter?.accepts(e))return;if(e.data?.type==='lab-runtime-back'){if(runtimeContext==='learn')navigate('learn');else openInstrument(currentDeviceId)}else if(e.data?.type==='lab-progress')receiveDeviceProgress(currentDeviceId,e.data)});

applyPreferences();setupPlatform();let onboarded=false;try{onboarded=localStorage.getItem('ml-lab-onboarded')==='1'}catch{}showPage(location.hash.slice(1)||(onboarded?'home':'welcome'));

// Accessible skip target follows the current visible screen without changing the route.
document.querySelector('.skip-link').addEventListener('click',event=>{event.preventDefault();const panel=document.getElementById(currentPage+'Page');if(panel){panel.tabIndex=-1;panel.focus();panel.scrollIntoView({block:'start'})}});
